Assume Linux or macOS and that `fork` succeeds. What does this program print?

```c
#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>
int main(void) {
    pid_t pid = fork();
    if (pid == 0) {
        printf("child\n");
        return 0;
    }
    wait(NULL);
    printf("parent\n");
    return 0;
}
```

Assume Linux or macOS and that `fork` succeeds. What does this program print?

```c
#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>
int main(void) {
    int x = 10;
    if (fork() == 0) {
        x = 99;
        printf("child x=%d\n", x);
        return 0;
    }
    wait(NULL);
    printf("parent x=%d\n", x);
    return 0;
}
```

