Assume Linux or macOS, compiled with `-pthread`. What does this program print?

```c
#include <stdio.h>
#include <pthread.h>
static void *work(void *arg) {
    printf("thread\n");
    return arg;
}
int main(void) {
    pthread_t t;
    pthread_create(&t, NULL, work, NULL);
    pthread_join(t, NULL);
    printf("main\n");
    return 0;
}
```

Assume Linux or macOS, compiled with `-pthread`. What does this program print?

```c
#include <stdio.h>
#include <pthread.h>
static void *work(void *arg) {
    *(int *)arg = 42;
    return NULL;
}
int main(void) {
    int x = 1;
    pthread_t t;
    pthread_create(&t, NULL, work, &x);
    pthread_join(t, NULL);
    printf("%d\n", x);
    return 0;
}
```

Assume Linux or macOS, compiled with `-pthread`. Which outputs can this program produce?

```c
#include <stdio.h>
#include <pthread.h>
static void *say(void *arg) {
    printf("%s\n", (const char *)arg);
    return NULL;
}
int main(void) {
    pthread_t a, b;
    pthread_create(&a, NULL, say, "A");
    pthread_create(&b, NULL, say, "B");
    pthread_join(a, NULL);
    pthread_join(b, NULL);
