```

Assume Linux or macOS, compiled with `-pthread`. The loop is meant to give threads the numbers 0, 1 and 2. What is wrong?

```c
#include <stdio.h>
#include <pthread.h>
static void *show(void *arg) {
    printf("%d\n", *(int *)arg);
    return NULL;
}
int main(void) {
    pthread_t t[3];
    int i;
    for (i = 0; i < 3; i++)
        pthread_create(&t[i], NULL, show, &i);
    for (int k = 0; k < 3; k++)
        pthread_join(t[k], NULL);
    return 0;
}
```

Assume 64-bit Linux or macOS and a build without optimization (`cc -O0 -pthread`). Two threads each add $1$ to the shared counter $1{,}000{,}000$ times. What does `main` print?

```c
#include <stdio.h>
#include <pthread.h>
static long counter;
static void *work(void *a) {
    for (int i = 0; i < 1000000; i++) counter++;
    return a;
}
int main(void) {
    pthread_t t1, t2;
    pthread_create(&t1, NULL, work, NULL);
    pthread_create(&t2, NULL, work, NULL);
    pthread_join(t1, NULL); pthread_join(t2, NULL);
    printf("%ld\n", counter);
}
```

Assume 64-bit Linux or macOS. This is the same program as the racy counter, but `counter` is an `atomic_long` and each increment uses `atomic_fetch_add`. What does it print?

```c
#include <stdio.h>
#include <pthread.h>
#include <stdatomic.h>
static atomic_long counter;
static void *work(void *a) {
    for (int i = 0; i < 1000000; i++) atomic_fetch_add(&counter, 1);
    return a;
}
int main(void) {
    pthread_t t1, t2;
    pthread_create(&t1, NULL, work, NULL);
    pthread_create(&t2, NULL, work, NULL);
    pthread_join(t1, NULL); pthread_join(t2, NULL);
    printf("%ld\n", atomic_load(&counter));
}
```

