On Linux, one producer and one consumer share a ring buffer of $N = 4$ slots, using the semaphores `empty` (free slots) and `full` (filled slots). The producer blocks forever on its first `put`. What is wrong, and what is the fix?

```c
#include <semaphore.h>
#define N 4
static int buf[N], in, out;
static sem_t empty, full;
void put(int v) { sem_wait(&empty); buf[in] = v; in = (in + 1) % N; sem_post(&full); }
int get(void) { sem_wait(&full); int v = buf[out]; out = (out + 1) % N; sem_post(&empty); return v; }
void setup(void) { sem_init(&empty, 0, 0); sem_init(&full, 0, 0); }
```

The parent should always print `child` before `parent`, but it can print `parent` first. Assume Linux, compiled with `-pthread`. What is wrong, and what is the fix?

```c
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
static sem_t done;
static void *child(void *a) { puts("child"); sem_post(&done); return a; }
int main(void) {
    pthread_t t;
    sem_init(&done, 0, 1);
    pthread_create(&t, NULL, child, NULL);
    sem_wait(&done);
    puts("parent");
    pthread_join(t, NULL);
}
```

Assume Linux or macOS, compiled with `-pthread`. Thread 0 runs `run((void *)0)` and thread 1 runs `run((void *)1)`. Can this program hang, and what is the fix?

```c
#include <pthread.h>
static pthread_mutex_t m[2] = { PTHREAD_MUTEX_INITIALIZER, PTHREAD_MUTEX_INITIALIZER };
static void *run(void *p) {
    long i = (long)p;
    pthread_mutex_lock(&m[i]); pthread_mutex_lock(&m[1 - i]);
    pthread_mutex_unlock(&m[1 - i]); pthread_mutex_unlock(&m[i]);
    return 0;
}
int main(void) {
    pthread_t t[2];
    for (long i = 0; i < 2; i++) pthread_create(&t[i], 0, run, (void *)i);
    for (int i = 0; i < 2; i++) pthread_join(t[i], 0);
}
```

Assume Linux or macOS with clang or GCC. The program below is built with `cc -g -pthread -fsanitize=thread` and run. What does ThreadSanitizer report?

```c
#include <pthread.h>
static int n;
static void *f(void *a) { n++; return a; }
int main(void) {
    pthread_t t;
    pthread_create(&t, 0, f, 0);
    n++;
    pthread_join(t, 0);
    return 0;
}
```

Assume a 32-bit microcontroller with a (made-up) UART: status register at `0x40001000` (bit 0 set when a received byte is waiting), data register at `0x40001004`. `uart_read` busy-waits. What goes wrong if `volatile` is removed from the macros?

```c
#include <stdint.h>
#define UART_STATUS (*(volatile uint32_t *)0x40001000u)
#define UART_DATA   (*(volatile uint32_t *)0x40001004u)
#define RX_READY    (1u << 0)
uint8_t uart_read(void) {
    while ((UART_STATUS & RX_READY) == 0)
        ;
    return (uint8_t)UART_DATA;
}
```

This is a miniature **event loop**: it takes events one at a time and calls the handler for each kind. What does it print? Why does `total` need no lock?

```c
#include <stdio.h>
typedef void (*handler_t)(int);
static int total;
static void on_key(int v)   { total += v; printf("key %d\n", v); }
static void on_timer(int v) { total += v; printf("timer %d\n", v); }
int main(void) {
    handler_t table[2] = { on_key, on_timer };
    int kind[4] = { 0, 1, 0, 0 }, val[4] = { 5, 10, 20, 1 };
    for (int i = 0; i < 4; i++)
        table[kind[i]](val[i]);
    printf("total %d\n", total);
}
```
